53	// configureAccessReporter is the small part of the authenticated API used by
54	// onboarding. Keeping it narrow makes the state machine independently testable.
55	type configureAccessReporter interface {
56		ReportEnable(ctx context.Context, remoteURL string) (*api.EnableRepoResponse, error)
57	}
