293	func ensureConfigureLogin(ctx context.Context, outW, errW io.Writer, deps configureFlowDeps) (*authProfile, error) {
294		target, err := deps.resolveAuth(ctx)
295		if err != nil {
296			return nil, err
297		}
298		if target.token != "" {
299			if err := api.RequireSecureURL(target.coreURL); err != nil {
300				return nil, fmt.Errorf("context login server URL check: %w", err)
301			}
302			if profile, profileErr := deps.fetchProfile(ctx, target.coreURL, target.token); profileErr == nil {
303				return profile, nil
304			} else if !isKeychainTokenRejected(profileErr) {
305				return nil, fmt.Errorf("validate login: %w", profileErr)
306			}
307		}
308	
309		if err := deps.runLogin(ctx, outW, errW); err != nil {
310			return nil, fmt.Errorf("login: %w", err)
311		}
312		target, err = deps.resolveAuth(ctx)
313		if err != nil {
314			return nil, err
315		}
316		if target.token == "" {
317			return nil, errors.New("login completed without an active session")
318		}
319		if err := api.RequireSecureURL(target.coreURL); err != nil {
320			return nil, fmt.Errorf("context login server URL check: %w", err)
321		}
322		profile, err := deps.fetchProfile(ctx, target.coreURL, target.token)
323		if err != nil {
324			return nil, fmt.Errorf("validate login: %w", err)
325		}
326		fmt.Fprintf(outW, "✓ Logged in as %s\n", profile.Handle)
327		return profile, nil
328	}
