505	// configureFocusChangedMsg forces huh's dynamic titles to re-evaluate after a
506	// field transition. huh evaluates TitleFunc before it calls Blur/Focus while
507	// handling NextField, so without this follow-up frame the help bar changes but
508	// the old section keeps the active-colored question mark until another keypress.
509	type configureFocusChangedMsg struct{}
510	
511	func configureRefreshFocus() tea.Cmd {
512		return func() tea.Msg { return configureFocusChangedMsg{} }
513	}
