1158	func configureFormTheme() huh.Theme {
1159		return huh.ThemeFunc(func(isDark bool) *huh.Styles {
1160			theme := uiform.Theme().Theme(isDark)
1161			success := lipgloss.Color(palette.Success)
1162			muted := lipgloss.Color(palette.Muted)
1163	
1164			// Radio and checkbox lists use the same active-row indicator. Selection
1165			// remains green and independent from the orange `>` cursor.
1166			theme.FieldSeparator = lipgloss.NewStyle().SetString("")
1167			theme.Focused.Base = lipgloss.NewStyle()
1168			theme.Blurred.Base = lipgloss.NewStyle()
1169			theme.Focused.SelectSelector = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Warning)).SetString("> ")
1170			theme.Blurred.SelectSelector = lipgloss.NewStyle().SetString("  ")
